37	// TestReadAggregateLinesEOFVsReadError checks the primitive directly: clean
38	// EOF delivers one final unterminated line; a non-EOF error never does.
39	func TestReadAggregateLinesEOFVsReadError(t *testing.T) {
40		t.Run("clean EOF keeps unterminated final line", func(t *testing.T) {
41			got, err := collectLines(t, strings.NewReader("a\nb\r\nc"))
42			if err != nil {
43				t.Fatalf("unexpected error: %v", err)
44			}
45			want := []collectedLine{{"a", 1}, {"b", 2}, {"c", 3}}
46			if fmt.Sprint(got) != fmt.Sprint(want) {
47				t.Fatalf("lines = %v, want %v (CR stripped, final line kept)", got, want)
48			}
49		})
50		t.Run("EOF exactly on a newline adds no blank line", func(t *testing.T) {
51			got, err := collectLines(t, strings.NewReader("a\n"))
52			if err != nil {
53				t.Fatalf("unexpected error: %v", err)
54			}
55			want := []collectedLine{{"a", 1}}
56			if fmt.Sprint(got) != fmt.Sprint(want) {
57				t.Fatalf("lines = %v, want %v", got, want)
58			}
59		})
60		t.Run("blank physical lines count", func(t *testing.T) {
61			got, err := collectLines(t, strings.NewReader("\n\nthird\n"))
62			if err != nil {
63				t.Fatalf("unexpected error: %v", err)
64			}
65			want := []collectedLine{{"", 1}, {"", 2}, {"third", 3}}
66			if fmt.Sprint(got) != fmt.Sprint(want) {
67				t.Fatalf("lines = %v, want %v", got, want)
68			}
69		})
70		t.Run("read error drops the unterminated tail", func(t *testing.T) {
71			input := "first\nsecond\ntail-without-newline"
72			failAt := len("first\nsecond\n") + len("tail-without-newline")
73			got, err := collectLines(t, &failingAfterReader{
74				data: []byte(input), failAt: failAt, err: errSentinelChunkedRead,
75			})
76			if !errors.Is(err, errSentinelChunkedRead) {
77				t.Fatalf("error = %v, want the reader's original error via errors.Is", err)
78			}
79			want := []collectedLine{{"first", 1}, {"second", 2}}
80			if fmt.Sprint(got) != fmt.Sprint(want) {
81				t.Fatalf("lines = %v, want only newline-terminated lines %v", got, want)
82			}
83		})
84		t.Run("error with bytes still completes co-delivered lines", func(t *testing.T) {
85			// One Read hands back a complete line, an unterminated tail and the
86			// error together. Only the complete line is delivered.
87			input := "first\ndangling"
88			got, err := collectLines(t, &failingAfterReader{
89				data: []byte(input), failAt: len(input),
90				err: errSentinelChunkedRead, errOnBoundary: true,
91			})
92			if !errors.Is(err, errSentinelChunkedRead) {
93				t.Fatalf("error = %v, want reader error", err)
94			}
95			want := []collectedLine{{"first", 1}}
96			if fmt.Sprint(got) != fmt.Sprint(want) {
97				t.Fatalf("lines = %v, want %v", got, want)
98			}
99		})
100		t.Run("callback error wins over a co-arriving read error", func(t *testing.T) {
101			stop := errors.New("callback stop")
102			var delivered int
103			r := &failingAfterReader{
104				data:   []byte("first\nrest"),
105				failAt: len("first\nrest"),
106				err:    errSentinelChunkedRead, errOnBoundary: true,
107			}
108			err := readAggregateLines(r, func(string, int) error {
109				delivered++
110				return stop
111			})
112			if !errors.Is(err, stop) {
113				t.Fatalf("error = %v, want callback error to take precedence", err)
114			}
115			if delivered != 1 {
116				t.Fatalf("callback ran %d times, want 1", delivered)
117			}
118		})
119		t.Run("tail is dropped byte by byte too", func(t *testing.T) {
120			input := "first\nsecond\ndangling"
121			failAt := len(input)
122			got, err := collectLines(t, &failingAfterReader{
123				data: []byte(input), failAt: failAt,
124				err: errSentinelChunkedRead, chunk: 1, errOnBoundary: true,
125			})
126			if !errors.Is(err, errSentinelChunkedRead) {
127				t.Fatalf("error = %v, want reader error", err)
128			}
129			want := []collectedLine{{"first", 1}, {"second", 2}}
130			if fmt.Sprint(got) != fmt.Sprint(want) {
131				t.Fatalf("lines = %v, want %v", got, want)
132			}
133		})
134	}
