417		}
418	}
419	
420	// TestReadAggregateErrorUnterminatedIdleDoesNotCloseWindows: an idle
421	// declaration whose newline never arrives must not move the partitioned
422	// effective watermark or close anything.
423	func TestReadAggregateErrorUnterminatedIdleDoesNotCloseWindows(t *testing.T) {
424		input := strings.Join([]string{
425			`{"type":"event","key":"k","time":100,"value":2,"partition":0}`,
426			`{"type":"watermark","time":1000,"partition":0}`,
427			`{"type":"idle","partition":1}`, // would make the effective watermark 1000
428		}, "\n")
429		var out, late bytes.Buffer
430		err := RunAggregatePartitionedSliding(&failingAfterReader{
431			data: []byte(input), failAt: len(input),
432			err: errSentinelChunkedRead, errOnBoundary: true,
433		}, 1000, 1000, 2, &out, &late)
434		if !errors.Is(err, errSentinelChunkedRead) {
435			t.Fatalf("error = %v, want reader error", err)
436		}
437		if out.String() != "" {
438			t.Fatalf("unterminated idle declaration must not close [0,1000): %q", out.String())
439		}
440	
441		// Control: the same idle record WITH a newline delivered together with
442		// the read error closes the window before the failure surfaces.
443		terminated := input + "\n"
444		var out2, late2 bytes.Buffer
445		err2 := RunAggregatePartitionedSliding(&failingAfterReader{
446			data: []byte(terminated), failAt: len(terminated),
447			err: errSentinelChunkedRead, errOnBoundary: true,
448		}, 1000, 1000, 2, &out2, &late2)
449		if !errors.Is(err2, errSentinelChunkedRead) {
450			t.Fatalf("control error = %v, want reader error", err2)
451		}
452		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
453		if out2.String() != want {
454			t.Fatalf("newline-terminated idle record must close the window first:\n got: %q\nwant: %q", out2.String(), want)
455		}
456	}
457	
458	// TestReadAggregateErrorEarlierRecordOrOutputFailureKept: a record error or an
459	// output write error on a complete line delivered by the same Read that
460	// carries the read failure must remain the reported failure; the read error,
461	// learned only afterwards, must not overwrite it.
462	func TestReadAggregateErrorEarlierRecordOrOutputFailureKept(t *testing.T) {
463		t.Run("record error on a complete line wins", func(t *testing.T) {
464			input := `{"type":"bogus"}` + "\n" + `{"type":"watermark","time":1000}`
465			var out, late bytes.Buffer
466			err := RunAggregate(&failingAfterReader{
467				data: []byte(input), failAt: len(input),
468				err: errSentinelChunkedRead, errOnBoundary: true,
469			}, 1000, &out, &late)
470			var ie *InputError
471			if !errors.As(err, &ie) || ie.Line != 1 {
472				t.Fatalf("error = %v, want *InputError on physical line 1", err)
473			}
474			if errors.Is(err, errSentinelChunkedRead) {
475				t.Fatalf("the record error must replace the later read error: %v", err)
476			}
477		})
478		t.Run("output write error on a complete line wins", func(t *testing.T) {
479			input := strings.Join([]string{
480				`{"type":"event","key":"k","time":100,"value":2}`,
481				`{"type":"watermark","time":1000}`,
482				`{"type":"event","key":"k","time":900,"value":3}`, // unterminated tail
483			}, "\n")
484			var late bytes.Buffer
485			err := RunAggregate(&failingAfterReader{
486				data: []byte(input), failAt: len(input),
487				err: errSentinelChunkedRead, errOnBoundary: true,
488			}, 1000, &errOnlyWriter{err: errSentinelOutput}, &late)
489			var oe *OutputError
490			if !errors.As(err, &oe) {
491				t.Fatalf("error = %v, want *OutputError", err)
492			}
493			if !errors.Is(err, errSentinelOutput) {
494				t.Fatalf("errors.Is must reach the writer error: %v", err)
495			}
496			if errors.Is(err, errSentinelChunkedRead) {
497				t.Fatalf("the output error must replace the read error learned after it: %v", err)
498			}
499		})
500	}
501	
502	// TestReadAggregateCleanEOFContractStillHolds summarizes the behavior that had
503	// to stay byte-identical through the reader rewrite: a valid final record
504	// without a trailing newline processes at clean EOF, while a damaged final
505	// record is an input error carrying its physical line number.
506	func TestReadAggregateCleanEOFContractStillHolds(t *testing.T) {
507		t.Run("valid unterminated final record processes", func(t *testing.T) {
508			input := `{"type":"event","key":"k","time":100,"value":2}` + "\n" +
509				`{"type":"watermark","time":1000}`
510			var out, late bytes.Buffer
511			if err := RunAggregate(strings.NewReader(input), 1000, &out, &late); err != nil {
512				t.Fatalf("clean EOF: %v", err)
513			}
514			want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
515			if out.String() != want {
516				t.Fatalf("got %q, want %q", out.String(), want)
517			}
518		})
519		t.Run("damaged unterminated final record is a line-numbered input error", func(t *testing.T) {
520			input := `{"type":"event","key":"k","time":100,"value":2}` + "\n" +
521				`{"type":"watermark","time":1000`
522			var out, late bytes.Buffer
523			err := RunAggregate(strings.NewReader(input), 1000, &out, &late)
524			var ie *InputError
525			if !errors.As(err, &ie) || ie.Line != 2 {
526				t.Fatalf("error = %v, want *InputError on physical line 2", err)
527			}
528			if !strings.Contains(ie.Reason, "invalid JSON") {
529				t.Fatalf("reason = %q, want invalid JSON", ie.Reason)
530			}
531			if out.String() != "" {
532				t.Fatalf("nothing may be emitted: %q", out.String())
533			}
534		})
535	}
